"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";
import { 
  User, CheckCircle, XCircle, Clock, 
  Settings, Volume2, VolumeX, Zap, Camera, ScanFace,
  QrCode, Calendar, Plus, ChevronDown, MapPin, 
  Target, Users, Info, Loader2, RefreshCw, X,
  ShieldCheck, AlertTriangle
} from "lucide-react";
import TourGuide from "@/components/TourGuide";
import { scanAbsensi, createAcara, getDaftarAcara, getLogsByAcara } from "@/lib/actions"; 
import { Html5Qrcode } from "html5-qrcode";

const absensiTourSteps = [
    { target: '.tour-acara-header', content: 'Kelola sesi absensi aktif Anda di sini.', disableBeacon: true },
    { target: '.tour-scanner-box', content: 'Scanner otomatis yang tajam dan responsif.', },
    { target: '.tour-activity-stream', content: 'Log kehadiran real-time yang tersimpan aman di database.', placement: 'left' as const },
];

export default function ScanClient() {
  const [isClient, setIsClient] = useState(false);
  const [logs, setLogs] = useState<any[]>([]);
  const [scanResult, setScanResult] = useState<any>(null);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [isLoadingLogs, setIsLoadingLogs] = useState(false);
  const [isSubmittingAcara, setIsSubmittingAcara] = useState(false);
  
  const [daftarAcara, setDaftarAcara] = useState<any[]>([]);
  const [selectedAcaraId, setSelectedAcaraId] = useState<number | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newAcara, setNewAcara] = useState({ nama: "", tanggal: new Date().toISOString().split('T')[0], lokasi: "Sekolah" });

  const scannerRef = useRef<Html5Qrcode | null>(null);

  // 1. DATA LOADING
  const loadData = useCallback(async (autoSelectLatest = false) => {
    setIsLoadingLogs(true);
    try {
        const list = await getDaftarAcara();
        setDaftarAcara(list);
        
        if (list.length > 0) {
            let targetId = selectedAcaraId;
            if (autoSelectLatest || !selectedAcaraId) {
                targetId = list[0].id;
                setSelectedAcaraId(targetId);
            }

            if (targetId) {
                const currentLogs = await getLogsByAcara(targetId);
                formatAndSetLogs(currentLogs);
            }
        }
    } catch (err) {
        console.error("Gagal memuat data:", err);
    } finally {
        setIsLoadingLogs(false);
    }
  }, [selectedAcaraId]);

  const formatAndSetLogs = (data: any[]) => {
    setLogs(data.map(item => ({
        name: item.pengurus.nama,
        role: item.pengurus.jabatan,
        image: item.pengurus.fotoUrl,
        time: new Date(item.tanggal).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }),
        status: item.status,
        scanId: item.id
    })));
  };

  useEffect(() => {
    setIsClient(true);
    loadData();
  }, []);

  // 2. SCANNER LOGIC (STABILIZED)
  const startScanner = async () => {
    if (!isClient || !selectedAcaraId) return;
    
    try {
        const element = document.getElementById("reader");
        if (!element) return;

        // Bersihkan instance lama
        if (scannerRef.current) {
            try { await scannerRef.current.stop(); } catch (e) {}
            scannerRef.current = null;
        }

        const html5QrCode = new Html5Qrcode("reader");
        scannerRef.current = html5QrCode;
        
        const config = { 
            fps: 15, 
            qrbox: { width: 250, height: 250 },
            aspectRatio: 1.0 
        };

        await html5QrCode.start(
            { facingMode: "environment" }, 
            config,
            (text) => handleScan(text),
            () => {}
        );
    } catch (err) {
        console.warn("Scanner failed to start. Elements might not be ready.");
    }
  };

  // Restart scanner saat ID acara berubah atau halaman dimuat
  useEffect(() => {
    if (isClient && selectedAcaraId) {
        const timer = setTimeout(() => startScanner(), 800);
        return () => {
            clearTimeout(timer);
            if (scannerRef.current && scannerRef.current.isScanning) {
                scannerRef.current.stop().catch(() => {});
            }
        };
    }
  }, [isClient, selectedAcaraId]);

  // 3. HANDLERS
  const handleScan = async (nis: string) => {
    if (!nis || scanResult || !selectedAcaraId) return;
    
    if (soundEnabled) {
        new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play().catch(() => {});
    }

    try {
        const result = await scanAbsensi(nis, selectedAcaraId);
        if (result.success && result.data) {
            const timestamp = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
            const newLog = { ...result.data, time: timestamp, scanId: Date.now() };
            setScanResult({ type: 'success', data: newLog, message: result.message });
            loadData(); 
        } else {
            setScanResult({ type: 'error', message: result.message });
        }
    } catch (err) {
        setScanResult({ type: 'error', message: "Koneksi Bermasalah" });
    }
    setTimeout(() => { setScanResult(null); }, 2500);
  };

  const handleAddAcara = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAcara.nama) return alert("Nama acara wajib diisi!");
    
    setIsSubmittingAcara(true);
    try {
        const formData = new FormData();
        formData.append("nama", newAcara.nama);
        formData.append("tanggal", newAcara.tanggal);
        formData.append("lokasi", newAcara.lokasi);

        const res = await createAcara(formData);
        if (res.success) {
            setIsModalOpen(false);
            setNewAcara({ nama: "", tanggal: new Date().toISOString().split('T')[0], lokasi: "Sekolah" });
            await loadData(true); 
        } else {
            alert("GAGAL: " + res.message);
        }
    } catch (error: any) {
        alert("ERROR: Gagal terhubung ke database. " + (error.message || ""));
    } finally {
        setIsSubmittingAcara(false);
    }
  };

  const selectedAcara = daftarAcara.find(a => a.id === selectedAcaraId);

  return (
    <div className="h-[calc(100vh-6rem)] flex flex-col xl:flex-row gap-8 font-sans p-2 overflow-hidden">
      
      {/* LEFT: SCANNING ENGINE */}
      <div className="w-full xl:w-[480px] flex flex-col gap-6 shrink-0 h-full">
        
        {/* ACARA CONTROL GLASS CARD */}
        <div className="bg-white/80 dark:bg-slate-900/60 backdrop-blur-2xl p-6 rounded-[2.5rem] border border-slate-200 dark:border-white/5 shadow-xl tour-acara-header">
            <div className="flex items-center justify-between mb-5">
                <div>
                    <h2 className="text-xl font-black text-slate-900 dark:text-white flex items-center gap-3 tracking-tight">
                        <div className="p-2.5 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-500/30">
                            <Target size={20} />
                        </div>
                        Sesi Absensi
                    </h2>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => loadData()} className="p-3 bg-slate-100 dark:bg-white/5 text-slate-500 hover:text-blue-600 rounded-2xl transition-all">
                        <RefreshCw size={18} className={isLoadingLogs ? "animate-spin" : ""} />
                    </button>
                    <button onClick={() => setIsModalOpen(true)} className="p-3 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-600/20 hover:scale-105 active:scale-95 transition-all">
                        <Plus size={18} strokeWidth={3} />
                    </button>
                </div>
            </div>

            <div className="relative">
                <select 
                    value={selectedAcaraId || ""} 
                    onChange={(e) => setSelectedAcaraId(Number(e.target.value))}
                    className="w-full pl-6 pr-12 py-4 bg-slate-100/50 dark:bg-slate-800/50 border border-slate-200 dark:border-white/10 rounded-[1.5rem] outline-none text-xs font-black text-slate-800 dark:text-white appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                >
                    {daftarAcara.length > 0 ? (
                        daftarAcara.map(a => (
                            <option key={a.id} value={a.id}>{a.nama}</option>
                        ))
                    ) : (
                        <option disabled value="">Belum ada acara...</option>
                    )}
                </select>
                <ChevronDown size={18} className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            </div>

            {selectedAcara && (
                <div className="mt-4 p-4 rounded-2xl bg-blue-500/5 border border-blue-500/10 flex items-center gap-4">
                    <div className="w-10 h-10 bg-white dark:bg-slate-800 rounded-xl shadow-sm flex items-center justify-center text-blue-600 shrink-0">
                        <Calendar size={18} />
                    </div>
                    <div className="min-w-0">
                        <h4 className="text-xs font-black text-blue-900 dark:text-blue-300 uppercase truncate">{selectedAcara.nama}</h4>
                        <p className="text-[10px] font-bold text-blue-600/70 mt-0.5 flex items-center gap-1"><MapPin size={10}/> {selectedAcara.lokasi}</p>
                    </div>
                </div>
            )}
        </div>

        {/* SCANNER VIEWPORT */}
        <div className="flex-1 min-h-[400px] bg-slate-900 rounded-[3rem] relative overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 tour-scanner-box group">
            {/* Background Camera Layer */}
            <div id="reader" className="absolute inset-0 z-0 [&>video]:object-cover [&>video]:h-full [&>video]:w-full"></div>
            
            {/* UI SCANNER Layer */}
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center p-12 pointer-events-none">
                <div className="relative w-full h-full max-w-[300px] max-h-[300px] border-2 border-white/10 rounded-3xl">
                    <div className="absolute -top-1 -left-1 w-12 h-12 border-t-4 border-l-4 border-blue-500 rounded-tl-3xl shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -top-1 -right-1 w-12 h-12 border-t-4 border-r-4 border-blue-500 rounded-tr-3xl shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -bottom-1 -left-1 w-12 h-12 border-b-4 border-l-4 border-blue-500 rounded-bl-3xl shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    <div className="absolute -bottom-1 -right-1 w-12 h-12 border-b-4 border-r-4 border-blue-500 rounded-br-3xl shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
                    
                    {!scanResult && (
                        <motion.div 
                            animate={{ top: ["5%", "95%", "5%"] }} 
                            transition={{ duration: 2, repeat: Infinity, ease: "linear" }}
                            className="absolute left-[10%] w-[80%] h-0.5 bg-blue-400 shadow-[0_0_20px_rgba(59,130,246,1)]"
                        />
                    )}

                    <AnimatePresence>
                        {scanResult && (
                            <motion.div 
                                initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                                className={`absolute inset-0 flex flex-col items-center justify-center text-center rounded-3xl z-50 pointer-events-auto backdrop-blur-2xl ${scanResult.type === 'success' ? (scanResult.data.status === 'DUPLICATE' ? 'bg-amber-900/90' : 'bg-emerald-900/90') : 'bg-rose-950/90'}`}
                            >
                                {scanResult.type === 'success' ? (
                                    <>
                                        <div className="w-24 h-24 rounded-full p-1.5 mb-4 shadow-2xl bg-white/20">
                                            <div className="relative w-full h-full rounded-full overflow-hidden border-2 border-white">
                                                <Image src={scanResult.data.image || "https://source.unsplash.com/random/100x100/?portrait"} alt="User" fill className="object-cover" />
                                            </div>
                                        </div>
                                        <h2 className="text-xl font-black text-white mb-1">{scanResult.data.name}</h2>
                                        <div className={`px-5 py-2 rounded-xl font-black text-[10px] uppercase shadow-xl bg-white ${scanResult.data.status === 'DUPLICATE' ? 'text-amber-700' : 'text-emerald-700'}`}>
                                            {scanResult.message}
                                        </div>
                                    </>
                                ) : (
                                    <>
                                        <XCircle size={64} className="text-rose-500 mb-4" />
                                        <p className="text-xs text-white font-black uppercase tracking-widest">{scanResult.message}</p>
                                    </>
                                )}
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>

            <div className="absolute bottom-6 left-0 w-full z-40 px-8">
                <div className="bg-slate-900/80 backdrop-blur-xl px-5 py-3 rounded-2xl border border-white/10 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="flex h-2 w-2 relative"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-75"></span><span className="relative inline-flex rounded-full h-2 w-2 bg-blue-500"></span></div>
                        <span className="text-[10px] font-black text-blue-200 uppercase tracking-widest">Scanner Ready</span>
                    </div>
                    <button onClick={() => setSoundEnabled(!soundEnabled)} className="text-slate-400 hover:text-white transition-colors">
                        {soundEnabled ? <Volume2 size={18}/> : <VolumeX size={18}/>}
                    </button>
                </div>
            </div>
        </div>
      </div>

      {/* RIGHT: ACTIVITY FEED */}
      <div className="flex-1 flex flex-col gap-6 h-full overflow-hidden">
        
        {/* STATS */}
        <div className="grid grid-cols-2 gap-4">
            <div className="bg-white dark:bg-slate-900/50 backdrop-blur-2xl p-6 rounded-[2rem] border border-slate-200 dark:border-white/5 shadow-sm">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Hadir</p>
                <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter">{logs.filter(l => l.status === 'HADIR').length}</span>
                </div>
            </div>
            <div className="bg-blue-600 p-6 rounded-[2rem] text-white shadow-xl shadow-blue-600/20 flex flex-col justify-center">
                <p className="text-[10px] font-black opacity-70 uppercase tracking-widest mb-1">Session</p>
                <h4 className="text-sm font-black truncate">{selectedAcara?.nama || "Pilih Acara"}</h4>
            </div>
        </div>

        {/* LOG LIST */}
        <div className="flex-1 bg-white/50 dark:bg-slate-900/50 backdrop-blur-2xl rounded-[2.5rem] border border-slate-200 dark:border-white/5 shadow-xl flex flex-col overflow-hidden tour-activity-stream">
            <div className="p-6 border-b border-slate-200 dark:border-white/5 flex items-center justify-between bg-white/50 dark:bg-transparent">
                <h3 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-wider flex items-center gap-3">
                    <Zap size={18} className="text-amber-500" fill="currentColor"/> 
                    Live Activity {isLoadingLogs && <Loader2 size={16} className="animate-spin" />}
                </h3>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                <AnimatePresence mode="popLayout">
                    {logs.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center opacity-20">
                            <ScanFace size={80} className="mb-4" />
                            <p className="text-[10px] font-black uppercase tracking-widest">Waiting for scan...</p>
                        </div>
                    ) : (
                        logs.map((log) => (
                            <motion.div 
                                key={log.scanId} layout initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}
                                className="flex items-center gap-4 p-3 rounded-2xl bg-white dark:bg-slate-800/50 border border-slate-100 dark:border-white/5 shadow-sm"
                            >
                                <div className="relative w-11 h-11 rounded-xl overflow-hidden shrink-0 shadow-md">
                                    <Image src={log.image || "https://source.unsplash.com/random/100x100/?portrait"} alt={log.name} fill className="object-cover" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <h4 className="text-sm font-black text-slate-900 dark:text-white truncate">{log.name}</h4>
                                    <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase">{log.role}</p>
                                </div>
                                <div className="text-right">
                                    <p className="text-xs font-black text-blue-600">{log.time}</p>
                                    <span className={`text-[8px] font-black px-2 py-0.5 rounded-full uppercase ${log.status === 'DUPLICATE' ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                        {log.status === 'DUPLICATE' ? 'Double' : 'Hadir'}
                                    </span>
                                </div>
                            </motion.div>
                        ))
                    )}
                </AnimatePresence>
            </div>
        </div>
      </div>

      {/* MODAL: NEW EVENT */}
      <AnimatePresence>
        {isModalOpen && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" />
                <motion.div 
                    initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }}
                    className="relative w-full max-w-md bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-white/20 overflow-hidden"
                >
                    <div className="p-8">
                        <div className="flex justify-between items-center mb-8">
                            <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tighter">New Event</h2>
                            <button onClick={() => setIsModalOpen(false)} className="p-2 bg-slate-100 dark:bg-white/5 rounded-xl"><X size={20}/></button>
                        </div>
                        
                        <form onSubmit={handleAddAcara} className="space-y-5">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Event Title</label>
                                <input required value={newAcara.nama} onChange={e => setNewAcara({...newAcara, nama: e.target.value})} type="text" placeholder="e.g. Rapat Pleno" className="w-full px-5 py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl outline-none text-sm font-bold dark:text-white border-2 border-transparent focus:border-blue-500 transition-all" />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Date</label>
                                    <input required value={newAcara.tanggal} onChange={e => setNewAcara({...newAcara, tanggal: e.target.value})} type="date" className="w-full px-5 py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl outline-none text-sm font-bold dark:text-white border-2 border-transparent focus:border-blue-500 transition-all" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Location</label>
                                    <input required value={newAcara.lokasi} onChange={e => setNewAcara({...newAcara, lokasi: e.target.value})} type="text" placeholder="Sekolah" className="w-full px-5 py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl outline-none text-sm font-bold dark:text-white border-2 border-transparent focus:border-blue-500 transition-all" />
                                </div>
                            </div>
                            <button disabled={isSubmittingAcara} type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50">
                                {isSubmittingAcara ? "Deploying..." : "Create Event"}
                            </button>
                        </form>
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>

      <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #3b82f6; border-radius: 10px; }
      `}</style>

    </div>
  );
}